=== FILE: sync_fifo.v ===
`timescale 1ns / 1ps
`default_nettype none

// sync_fifo: single-clock first-in, first-out buffer.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
//  - Storage: DEPTH x WIDTH array, not reset (datapath).
//  - Pointers wrap from DEPTH-1 to 0 by compare, so any DEPTH >= 2 works.
//  - Occupancy is an explicit count register; full/empty are compares on it.
//  - First-word fall-through: rd_data = mem[rd_ptr].
//  - Write while full is dropped, read while empty is ignored.
//  - Reset: synchronous, active low; clears pointers and count.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer PW = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer CW = $clog2(DEPTH + 1);

    localparam [PW-1:0] PTR_ZERO = 0;
    localparam [PW-1:0] PTR_ONE  = 1;
    localparam [PW-1:0] LAST     = DEPTH[PW-1:0] - PTR_ONE;
    localparam [CW-1:0] CNT_ZERO = 0;
    localparam [CW-1:0] CNT_ONE  = 1;
    localparam [CW-1:0] CNT_FULL = DEPTH[CW-1:0];

    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [PW-1:0] wr_ptr_q;
    reg [PW-1:0] wr_ptr_d;
    reg [PW-1:0] rd_ptr_q;
    reg [PW-1:0] rd_ptr_d;
    reg [CW-1:0] count_q;
    reg [CW-1:0] count_d;

    // Flags are compares on a register: no input-to-flag combinational path.
    assign full    = (count_q == CNT_FULL);
    assign empty   = (count_q == CNT_ZERO);
    assign count   = count_q;
    assign rd_data = mem[rd_ptr_q];

    // Accepted requests: the flags gate the requests (overflow/underflow policy).
    wire wr_acc = wr_en & ~full;
    wire rd_acc = rd_en & ~empty;
    wire mem_we = rst_n & wr_acc;

    // Next write pointer.
    always @* begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST) begin
                wr_ptr_d = PTR_ZERO;
            end else begin
                wr_ptr_d = wr_ptr_q + PTR_ONE;
            end
        end
    end

    // Next read pointer.
    always @* begin
        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_ptr_q == LAST) begin
                rd_ptr_d = PTR_ZERO;
            end else begin
                rd_ptr_d = rd_ptr_q + PTR_ONE;
            end
        end
    end

    // Next count: up on write only, down on read only, else hold.
    always @* begin
        count_d = count_q;
        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // Control registers, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= PTR_ZERO;
            rd_ptr_q <= PTR_ZERO;
            count_q  <= CNT_ZERO;
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage: written only outside reset, on an accepted write.
    always @(posedge clk) begin
        if (mem_we) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) if (!f_past_valid) assume (!rst_n);

    // wr_ptr is count slots after rd_ptr, modulo DEPTH.
    wire [CW:0] f_sum  = rd_ptr_q + count_q;
    wire [CW:0] f_wrap = (f_sum >= DEPTH) ? (f_sum - DEPTH) : f_sum;

    // One solver-chosen slot and the word last written there.
    (* anyconst *) reg [PW-1:0] f_addr;
    reg [WIDTH-1:0] f_data;
    always @(*) assume (f_addr <= LAST);

    always @(posedge clk)
        if (mem_we && (wr_ptr_q == f_addr))
            f_data <= wr_data;

    // Slot f_addr holds a live entry when its distance from rd_ptr is below count.
    wire [CW:0] f_dist = (f_addr >= rd_ptr_q) ? (f_addr - rd_ptr_q)
                                              : (f_addr + DEPTH - rd_ptr_q);
    wire f_in_use = (f_dist < count_q);

    always @(*) if (f_past_valid) begin
        assert (count_q <= CNT_FULL);
        assert (wr_ptr_q <= LAST);
        assert (rd_ptr_q <= LAST);
        assert (full  == (count_q == CNT_FULL));
        assert (empty == (count_q == CNT_ZERO));
        assert (!(full && empty));
        assert (wr_ptr_q == f_wrap[PW-1:0]);
        if (f_in_use) assert (mem[f_addr] == f_data);
        if (!empty && (rd_ptr_q == f_addr)) assert (rd_data == f_data);
    end

    always @(posedge clk) if (f_past_valid) begin
        if (!$past(rst_n)) begin
            assert (count_q  == CNT_ZERO);
            assert (wr_ptr_q == PTR_ZERO);
            assert (rd_ptr_q == PTR_ZERO);
        end else begin
            if ($past(wr_acc) && !$past(rd_acc)) assert (count_q == $past(count_q) + CNT_ONE);
            if ($past(rd_acc) && !$past(wr_acc)) assert (count_q == $past(count_q) - CNT_ONE);
            if ($past(wr_acc) == $past(rd_acc))  assert (count_q == $past(count_q));
            if ($past(wr_en) && $past(full))     assert (wr_ptr_q == $past(wr_ptr_q));
            if ($past(rd_en) && $past(empty))    assert (rd_ptr_q == $past(rd_ptr_q));
        end
    end

    // Covers: the FIFO fills, drains back to idle, and returns the tracked word.
    reg f_was_full;
    always @(posedge clk)
        if (!rst_n) f_was_full <= 1'b0;
        else if (full) f_was_full <= 1'b1;

    always @(*) if (f_past_valid) begin
        cover (full);
        cover (f_was_full && empty);
        cover (wr_en && rd_en && full);
        cover (rd_acc && f_in_use && (rd_ptr_q == f_addr));
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: sync_fifo_tb.v ===
`timescale 1ns / 1ps

// Per-configuration harness: one sync_fifo, an independent shift-queue model,
// per-cycle checks of count/full/empty/rd_data, and coverage goals.
module sync_fifo_harness #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        wr_en,
    input  wire        rd_en,
    input  wire [15:0] wr_data_in,
    output wire [31:0] passed,
    output wire [31:0] failed,
    output wire [9:0]  cov
);
    localparam integer CW = $clog2(DEPTH + 1);

    wire [WIDTH-1:0] wr_data = wr_data_in[WIDTH-1:0];
    wire             full;
    wire             empty;
    wire [WIDTH-1:0] rd_data;
    wire [CW-1:0]    count;

    sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full),
        .rd_en   (rd_en),
        .rd_data (rd_data),
        .empty   (empty),
        .count   (count)
    );

    // Reference queue: qv[WIDTH-1:0] is the oldest entry.
    reg [DEPTH*WIDTH-1:0] qv = {DEPTH*WIDTH{1'b0}};
    integer m_n  = 0;   // entries held
    integer m_wi = 0;   // accepted writes since reset, mod DEPTH
    integer m_ri = 0;   // accepted reads since reset, mod DEPTH
    integer k;
    reg acc_w = 1'b0;
    reg acc_r = 1'b0;
    reg was_full = 1'b0;
    reg started  = 1'b0;
    reg [9:0]  cov_r    = 10'd0;
    reg [31:0] passed_r = 32'd0;
    reg [31:0] failed_r = 32'd0;

    assign passed = passed_r;
    assign failed = failed_r;
    assign cov    = cov_r;

    // Coverage goals:
    // 0 filled to full          1 write while full       2 drained to empty after full
    // 3 read while empty        4 write+read when empty  5 write+read when full
    // 6 write+read in between   7 write pointer wrap     8 read pointer wrap
    // 9 reset during traffic
    always @(posedge clk) begin
        if (!rst_n) begin
            if (started && (m_n > 0)) cov_r[9] = 1'b1;
            started  = 1'b1;
            m_n      = 0;
            m_wi     = 0;
            m_ri     = 0;
            was_full = 1'b0;
        end else if (started) begin
            acc_w = wr_en && (m_n < DEPTH);
            acc_r = rd_en && (m_n > 0);
            if (m_n == DEPTH) begin
                cov_r[0] = 1'b1;
                was_full = 1'b1;
            end
            if ((m_n == 0) && was_full)                      cov_r[2] = 1'b1;
            if (wr_en && (m_n == DEPTH))                      cov_r[1] = 1'b1;
            if (rd_en && (m_n == 0))                          cov_r[3] = 1'b1;
            if (wr_en && rd_en && (m_n == 0))                 cov_r[4] = 1'b1;
            if (wr_en && rd_en && (m_n == DEPTH))             cov_r[5] = 1'b1;
            if (wr_en && rd_en && (m_n > 0) && (m_n < DEPTH)) cov_r[6] = 1'b1;
            if (acc_w && (m_wi == DEPTH - 1))                 cov_r[7] = 1'b1;
            if (acc_r && (m_ri == DEPTH - 1))                 cov_r[8] = 1'b1;
            if (acc_r) begin
                qv   = qv >> WIDTH;
                m_n  = m_n - 1;
                m_ri = (m_ri == DEPTH - 1) ? 0 : m_ri + 1;
            end
            if (acc_w) begin
                for (k = 0; k < DEPTH; k = k + 1)
                    if (k == m_n) qv[k*WIDTH +: WIDTH] = wr_data;
                m_n  = m_n + 1;
                m_wi = (m_wi == DEPTH - 1) ? 0 : m_wi + 1;
            end
        end
    end

    // Outputs are stable between edges; check them at every falling edge.
    always @(negedge clk) begin
        if (started) begin
            if (count === m_n[CW-1:0]) passed_r = passed_r + 1;
            else begin
                failed_r = failed_r + 1;
                $error("DEPTH=%0d count: got %0d, expected %0d at %0t", DEPTH, count, m_n, $time);
            end
            if (full === (m_n == DEPTH)) passed_r = passed_r + 1;
            else begin
                failed_r = failed_r + 1;
                $error("DEPTH=%0d full: got %b, expected count %0d at %0t", DEPTH, full, m_n, $time);
            end
            if (empty === (m_n == 0)) passed_r = passed_r + 1;
            else begin
                failed_r = failed_r + 1;
                $error("DEPTH=%0d empty: got %b, expected count %0d at %0t", DEPTH, empty, m_n, $time);
            end
            if ((full & empty) === 1'b0) passed_r = passed_r + 1;
            else begin
                failed_r = failed_r + 1;
                $error("DEPTH=%0d full and empty not exclusive at %0t", DEPTH, $time);
            end
            if (m_n > 0) begin
                if (rd_data === qv[WIDTH-1:0]) passed_r = passed_r + 1;
                else begin
                    failed_r = failed_r + 1;
                    $error("DEPTH=%0d rd_data: got %h, expected %h at %0t", DEPTH, rd_data, qv[WIDTH-1:0], $time);
                end
            end
        end
    end
endmodule

module sync_fifo_tb;
    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg        rst_n;
    reg        wr_en;
    reg        rd_en;
    reg [15:0] wr_data;

    wire [31:0] p8;
    wire [31:0] f8;
    wire [31:0] p5;
    wire [31:0] f5;
    wire [9:0]  c8;
    wire [9:0]  c5;

    sync_fifo_harness #(.DEPTH(8), .WIDTH(8)) h8 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .wr_data_in(wr_data), .passed(p8), .failed(f8), .cov(c8)
    );

    sync_fifo_harness #(.DEPTH(5), .WIDTH(12)) h5 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .wr_data_in(wr_data), .passed(p5), .failed(f5), .cov(c5)
    );

    integer        seed;
    integer        k;
    integer        dummy;
    reg [31:0]     rr;
    reg [31:0]     cov_pass;
    reg [31:0]     cov_fail;
    reg [31:0]     passed;
    reg [31:0]     failed;
    reg [8*64-1:0] nonce;

    // Drive one cycle of stimulus at the falling edge.
    task step(input r_n, input w, input r);
        begin
            @(negedge clk);
            rr      = $random(seed);
            rst_n   = r_n;
            wr_en   = w;
            rd_en   = r;
            wr_data = rr[15:0];
        end
    endtask

    // Random traffic: write with probability wp/16, read with rp/16.
    task random_phase(input integer n, input [3:0] wp, input [3:0] rp);
        integer j;
        reg [31:0] rq;
        begin
            for (j = 0; j < n; j = j + 1) begin
                rq = $random(seed);
                step(1'b1, (rq[3:0] < wp), (rq[7:4] < rp));
            end
        end
    endtask

    initial begin
        seed     = 32'h5EEDF1F0;
        rst_n    = 1'b0;
        wr_en    = 1'b0;
        rd_en    = 1'b0;
        wr_data  = 16'h0000;
        nonce    = {(8*64){1'b0}};
        cov_pass = 32'd0;
        cov_fail = 32'd0;

        // Reset, with requests that must be ignored.
        step(1'b0, 1'b1, 1'b1);
        step(1'b0, 1'b1, 1'b0);
        step(1'b0, 1'b0, 1'b1);

        // Read while empty.
        step(1'b1, 1'b0, 1'b1);
        step(1'b1, 1'b0, 1'b1);
        // Write and read together when empty: only the write is accepted.
        step(1'b1, 1'b1, 1'b1);
        // Fill to full and keep writing (write while full).
        repeat (10) step(1'b1, 1'b1, 1'b0);
        // Write and read together when full, then in between.
        repeat (2) step(1'b1, 1'b1, 1'b1);
        // Drain to empty and keep reading (read while empty); pointers wrap.
        repeat (10) step(1'b1, 1'b0, 1'b1);
        // Partial fill, simultaneous traffic in between, partial drain.
        repeat (3) step(1'b1, 1'b1, 1'b0);
        repeat (4) step(1'b1, 1'b1, 1'b1);
        repeat (3) step(1'b1, 1'b0, 1'b1);
        // Reset during traffic.
        repeat (3) step(1'b1, 1'b1, 1'b0);
        step(1'b0, 1'b1, 1'b1);
        step(1'b0, 1'b1, 1'b0);
        step(1'b1, 1'b0, 1'b0);

        // Random traffic with stalls on both sides.
        random_phase(400, 4'd12, 4'd6);
        random_phase(400, 4'd6, 4'd12);
        random_phase(400, 4'd8, 4'd8);
        // Second reset in the middle of random traffic.
        repeat (4) step(1'b1, 1'b1, 1'b0);
        step(1'b0, 1'b1, 1'b1);
        random_phase(300, 4'd9, 4'd9);

        // Settle and let the last checks run.
        repeat (3) step(1'b1, 1'b0, 1'b0);
        @(negedge clk);
        #1;

        // Coverage goals: each missing goal is a failed check.
        for (k = 0; k < 10; k = k + 1) begin
            if (c8[k] === 1'b1) cov_pass = cov_pass + 1;
            else begin
                cov_fail = cov_fail + 1;
                $error("DEPTH=8 coverage goal %0d not reached", k);
            end
            if (c5[k] === 1'b1) cov_pass = cov_pass + 1;
            else begin
                cov_fail = cov_fail + 1;
                $error("DEPTH=5 coverage goal %0d not reached", k);
            end
        end

        passed = p8 + p5 + cov_pass;
        failed = f8 + f5 + cov_fail;
        dummy  = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
